new PluginModular([
  {
    entries: ['features/*/index.ts'],
    entryKind: 'file',
    targetFile: path.resolve(rootDir, 'features.generated.ts'),
    template({ modules }) {
      return modules
        .map(({ moduleName, relativePath }) => `export * as ${moduleName} from './${relativePath}';`)
        .join('\n');
    },
  },
]),
